INSERT INTO public."nav_pages" ("id", "nav_item_id", "heading", "subheading", "hero_image", "sections", "is_published", "created_at", "updated_at", "form_config", "hero_config") VALUES ('0a1422b9-b86c-4824-9c8b-c8f01f499538', '4a9231a2-47b1-4616-8515-fc76b58ae446', '', '', 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/about/1787552298547-buxbiyxw2me.png', '[{"items":[{"icon":"PersonStanding","label":"Students Trained","number":"50+"},{"icon":"BookOpenCheck","label":"Courses","number":"20 +"},{"icon":"CircleArrowDown","label":"Learners","number":"10+"},{"icon":"HandCoins","label":"Expert Instructors","number":"5+"}],"hidden":false,"content":"Marvel Slice was founded with a clear mission: to bridge the gap between academic learning and industry expectations. What began as a small training initiative has grown into a trusted educational platform serving thousands of students across India.\n\nOur programs are designed collaboratively with industry experts to ensure every student gains the practical skills and confidence needed to excel in their chosen field. From technology and data science to competitive exam preparation, we offer comprehensive learning paths tailored to modern career demands.\n\nAt Marvel Slice, we believe education should be accessible, engaging, and outcome-driven. Our team of experienced instructors brings years of real-world expertise to every classroom, creating an environment where students don’t just learn — they thrive.","heading":"About Marvel Slice","image_url":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/about/1786203633601-26ip4rmxhnu.png","contentAlign":"center","headingAlign":"center","section_type":"text_stats"},{"items":[{"icon":"GraduationCap","title":"Industry-Aligned Curriculum","description":"Courses designed with input from hiring managers and industry leaders to ensure you learn what matters most."},{"icon":"Users","title":"Expert Instructors","description":"Learn from seasoned professionals with years of hands-on experience in their respective domains."},{"icon":"Briefcase","title":"Placement Assistance","description":"Dedicated career support including resume building, mock interviews, and direct referrals to partner companies."},{"icon":"Globe","title":"Flexible Learning","description":"Choose from online, offline, or hybrid modes to fit learning around your schedule and preferences."},{"icon":"Zap","title":"Hands-On Projects","description":"Apply your knowledge through real-world projects and case studies that build a standout portfolio."},{"icon":"Award","title":"Certification","description":"Earn industry-recognised certificates upon completion that add real value to your professional profile."},{"icon":"Clock","title":"Lifetime Access","description":"Get lifetime access to course materials, updates, and recordings so you can learn at your own pace."},{"icon":"TrendingUp","title":"Continuous Growth","description":"Regular curriculum updates keep pace with changing industry trends and emerging technologies."}],"heading":"Why Choose Marvel Slice?","subheading":"We are committed to delivering an education that truly makes a difference. Here’s what sets us apart.","section_type":"feature_grid"},{"hidden":true,"content":"Take the first step toward a brighter future. Get in touch with our team today.","heading":"Ready to Start Your Journey?","cta_link":"/contact","section_type":"cta"}]'::jsonb, TRUE, '2026-07-23T14:56:02.192514+00:00', '2026-08-24T06:18:23.00734+00:00', '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."nav_pages" ("id", "nav_item_id", "heading", "subheading", "hero_image", "sections", "is_published", "created_at", "updated_at", "form_config", "hero_config") VALUES ('83fe5d2a-3bed-445f-8a30-5146d7b75b46', 'a3122ef5-63ac-43d3-810a-905c6eafe896', 'Our services ', 'What We Offer', 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/1787552327337-11.png', '[{"items":[{"icon":"Camera","title":"Online Classes","description":"Learn from anywhere through live interactive sessions, recorded lectures, digital study materials, and continuous mentor support."},{"icon":"House","title":"Offline Classes","description":"Experience classroom-based learning with expert trainers, hands-on practical sessions, doubt clearing, and collaborative learning."},{"icon":"BookA","title":"Professional Courses","description":"Industry-focused programs in Programming, AI, Data Science, Cloud Computing, Cybersecurity, Full Stack Development, and more."},{"icon":"BriefcaseBusiness","title":"Placement Training","description":"Prepare for your dream job with aptitude training, coding practice, mock interviews, resume building, and HR interview preparation."},{"icon":"Handshake","title":"Soft Skills Development","description":"Build communication, leadership, teamwork, presentation, problem-solving, and professional etiquette for workplace success.Marvel Slice "},{"icon":"","title":"Hands-on Project Training","description":"Gain practical experience by working on real-world projects, case studies, and industry-based assignments to strengthen your portfolio."},{"icon":"Trophy","title":"Certification Programs","description":"Earn industry-recognized certifications that validate your skills and enhance your career opportunities with employers worldwide."},{"icon":"PersonStanding","title":"Career Guidance & Mentorship","description":"Receive personalized career counseling, one-on-one mentorship, learning roadmaps, and expert guidance to achieve your professional goals."}],"heading":"What We Offer","section_type":"cards"},{"items":[{"icon":"AArrowDown","image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/1786197924857-ChatGPT%20Image%20Mar%2031,%202026,%2011_11_04%20PM.png","title":"Enroll","number":"01","description":"Select a program and start your learning journey with dedicated, one-on-one counselor support."},{"icon":"Accessibility","image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/1786197924857-ChatGPT%20Image%20Mar%2031,%202026,%2011_11_04%20PM.png","title":"Learn","number":"02","description":"Master core concepts through interactive live sessions, practical labs, and expert-led course modules."},{"icon":"Building2","image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/1786197924857-ChatGPT%20Image%20Mar%2031,%202026,%2011_11_04%20PM.png","title":"Build","number":"03","description":"Apply your new skills to real-world projects and build a standout professional portfolio."},{"icon":"AlignEndHorizontal","image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/1786197924857-ChatGPT%20Image%20Mar%2031,%202026,%2011_11_04%20PM.png","title":"Assess","number":"04","description":"Track your growth with regular evaluations, detailed feedback, and comprehensive mock interview sessions."},{"icon":"AlignEndVertical","image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/1786197924857-ChatGPT%20Image%20Mar%2031,%202026,%2011_11_04%20PM.png","title":"Certify","number":"05","description":"Earn industry-recognized certifications that validate your expertise and boost your professional credibility."},{"icon":"AlarmSmoke","image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/1786198065010-ChatGPT%20Image%20Mar%2031,%202026,%2011_11_04%20PM.png","title":"Succeed","number":"06","description":"Launch your tech career with our dedicated placement support and strong hiring-partner network"}],"heading":"Your Learning Journey","features":[{"icon":"ClipboardCheck","title":"Personalized Guidance","colorHex":"#7C3AED","description":"One-on-one counselor support at every stage."},{"icon":"UserCheck","title":"Hands-on Learning","colorHex":"#EC4899","description":"Projects & labs to build real industry skills."},{"icon":"ClipboardList","title":"Career Support","colorHex":"#06B6D4","description":"Resume building, mock interviews & placements."},{"icon":"ShieldCheck","title":"Lifetime Access","colorHex":"#22C55E","description":"Access resources & updates even after you succeed."}],"subheading":"A structured path from enrollment to career success.","section_type":"timeline"},{"items":[{"answer":"Yes. We provide both online live classes and offline classroom training, allowing students to choose the learning mode that best fits their schedule and preferences.","question":"Do you offer both online and offline classes?"},{"answer":"Yes. Upon successfully completing the course and meeting the required criteria, you will receive an industry-recognized course completion certificate.","question":"Will I receive a certificate after completing the course?"},{"answer":"Yes. We offer comprehensive placement support, including resume building, aptitude training, mock interviews, soft skills development, and job assistance to help you start your career.","question":"Do you provide placement assistance?"},{"answer":"Absolutely. Our courses are designed for beginners, students, and working professionals. Experienced instructors guide you from the fundamentals to advanced concepts through practical learning.","question":"Are the courses suitable for beginners?"},{"answer":"You can enroll by contacting our admissions team, visiting our training center, or registering through our website. Our counselors will help you choose the right course based on your career goals.","question":"How can I enroll in a course?"}],"heading":"Frequently Asked Questions","subheading":"","section_type":"faq_list"}]'::jsonb, TRUE, '2026-07-13T16:26:42.324711+00:00', '2026-08-24T06:18:55.640661+00:00', '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
