INSERT INTO public."home_sections" ("id", "section_key", "heading", "subheading", "content", "is_active", "sort_order", "updated_at") VALUES ('447904c3-062c-40d6-a648-a9891f4271cb', 'empowering', 'Empowering Careers Through Quality Education', 'Bridging the gap between ambition and achievement', '{"description":"Welcome to the Training Department of Marvel Slice, where learning meets innovation and career success. Our department is dedicated to providing high-quality training programs in both Software Development and Competitive Exam Preparation to help students achieve academic excellence, technical expertise, and professional growth.\n\nWe focus on practical learning, skill enhancement, and career-oriented education through structured training programs, expert mentorship, and real-time practice sessions."}'::jsonb, TRUE, 4, '2026-08-24T04:34:27.535992+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."home_sections" ("id", "section_key", "heading", "subheading", "content", "is_active", "sort_order", "updated_at") VALUES ('10fef9ac-c827-48a7-8fc4-275415cc087b', 'services', 'Our Services', 'Comprehensive solutions for individuals and organizations', '{"intro":"We provide professional training programs for competitive exams, software development, and placement preparation. Our courses are designed with practical learning, expert guidance, and real-time training support. Join us to build skills, gain confidence, and achieve career success.","cta_link":"/services","cta_text":"Explore More Services","left_heading":"Transform Your Future with Industry-Focused Training","service_cards":[{"title":"Classroom Training","link_url":"/courses/nextjs-fullstack","image_url":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/home/1784811549405-r1bruoh1nbp.png","description":"Learn in a collaborative environment with face-to-face interaction.","is_clickable":true},{"title":"Online Learning","link_url":"/courses/nextjs-fullstack","image_url":"https://picsum.photos/seed/serv-online/400/250","description":"Study at your own pace with recorded sessions and live Q&A.","is_clickable":true},{"title":"Corporate Training","link_url":"/courses/nextjs-fullstack","image_url":"https://picsum.photos/seed/serv-corporate/400/250","description":"Tailored programs to meet your organization''s specific needs.","is_clickable":true},{"title":"Software Learning","link_url":"/courses","image_url":"https://picsum.photos/seed/serv-corporate/400/250","description":"Tailored programs to meet your organization''s specific needs.","is_clickable":true}],"services_list":[{"title":"Classroom Training","description":"Comprehensive coaching programs for TNPSC, UPSC, SSC, Banking, Railway, Police, and other government examinations with expert guidance and regular mock tests."},{"title":"Online Learning","icon_name":"globe","description":"Flexible self-paced and live online courses accessible from anywhere."},{"title":"Corporate Training","description":"Customized training programs for organizations to upskill their workforce."},{"title":"Placement Support","icon_name":"users","description":"End-to-end placement assistance including resume building, mock interviews, and job referrals."}],"left_image_url":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/home/1784624762489-ijhwnczbz5.png","left_description":"Our services are designed to meet the evolving needs of the job market. Whether you''re a student, professional, or organization, we have the right solution for you."}'::jsonb, TRUE, 6, '2026-08-24T04:34:28.152771+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."home_sections" ("id", "section_key", "heading", "subheading", "content", "is_active", "sort_order", "updated_at") VALUES ('3cdf230c-c234-4531-adc8-c43685324e44', 'hero', 'Transform Your Career', 'Expert-led training for a competitive edge', '{"stats":[{"label":"Courses","value":"10,000+"},{"label":"Success Stories","value":"8,500+"},{"label":"Placement Support","value":"95%"}],"slides":[{"image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/home/1787546049277-px8a93flljr.png","heading":"","description":""},{"image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/home/1787546052752-56inu4svac8.png","heading":"","description":""},{"image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/home/1787546060176-2375bzbhnig.png","heading":"","description":""}],"headline":"","hero_mode":"carousel","description":"Join thousands of successful students who have transformed their careers through our industry-focused training programs. Learn from experts, build real-world projects, and achieve your goals.","banner_image":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/home/1787160953549-yg24vmrh1ws.png","carousel_type":"image","banner_heading":"","feature_bullets":["Industry-Relevant Curriculum Designed by Experts","Hands-On Projects & Real-World Simulations","Personalized Mentorship & Career Guidance","Flexible Learning — Online & Offline Batches"],"banner_description":""}'::jsonb, TRUE, 0, '2026-08-24T04:34:26.255053+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."home_sections" ("id", "section_key", "heading", "subheading", "content", "is_active", "sort_order", "updated_at") VALUES ('f497b078-e76d-43ee-b9aa-9b4d57060cac', 'intro_form', 'Transform Your Career with Expert-Led Learning', '', '{"stats":[{"label":"Expert Trainers","value":"20+"},{"label":"Courses Offered","value":"100+"},{"label":"Students","value":"25+"}],"heading":"Transform Your Career with Expert-Led Learning","form_title":"Book Your Free Demo Class","intro_text":"Marvel Slice is a dynamic learning institute dedicated to empowering students, graduates, and aspiring professionals with the knowledge, skills, and confidence needed to succeed in today''s competitive world. We provide quality software training and competitive-exam coaching under one learning platform, helping students build both technical expertise and career opportunities.\nAt Marvel Slice, we believe that education should create opportunities, skills should create confidence, and consistent preparation should create success. Our mission is to provide an inspiring learning environment where every student can discover their potential, strengthen their abilities, and move confidently toward their academic and career goals.","pill_buttons":"Flexible Schedule\nPlacement Training\nHands-On Projects\nCompletive Exams"}'::jsonb, TRUE, 1, '2026-08-24T04:34:26.57161+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."home_sections" ("id", "section_key", "heading", "subheading", "content", "is_active", "sort_order", "updated_at") VALUES ('e15bf29e-43db-4b84-a6f8-bb45925a5185', 'featured_courses', 'Explore Our Top Programs', 'Choose from our most popular courses designed for career success', '{"cards":[{"bullets":["Full Stack Development","Java Development","Python Programming","React JS Training","Data Science","Python Programming"],"heading":"Software Learning","image_url":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/home/1784624668802-oj9pn18bsd.jpg","button_link":"/software-learning","button_text":"View More ","description":"Learn industry-demand technologies from expert trainers and build a successful IT career with practical training, live projects, and placement support."},{"bullets":["TNPSC Exams","Banking Exams","UPSC Civil Services","TET/TRB Exams","Aptitude and Reasoning Training","Railway Recruitment Exams"],"heading":"Competitive Exam","image_url":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/home/1784624676153-x0wa52civt.jpg","button_link":"/competitive-exam","button_text":"View More ","description":"Prepare for government jobs, banking exams, SSC, TNPSC, UPSC, railway exams, and other competitive examinations, updated study materials, and regular mock tests."}]}'::jsonb, TRUE, 5, '2026-08-24T04:34:27.855746+00:00') ON CONFLICT DO NOTHING;
