INSERT INTO public."home_sections" ("id", "section_key", "heading", "subheading", "content", "is_active", "sort_order", "updated_at") VALUES ('0f545b64-4490-4c9c-8100-daa1cb78660f', 'upcoming_image', '', '', '{"image_url":"https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/pages/home/1787416494426-bz24l00lwfw.jpeg","image_link":"/contact"}'::jsonb, TRUE, 3, '2026-08-24T04:34:27.216414+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."home_sections" ("id", "section_key", "heading", "subheading", "content", "is_active", "sort_order", "updated_at") VALUES ('c70ea839-40a1-494b-b763-9f5d6d9e98ba', 'faqs', 'Frequently Asked Questions', 'Everything you need to know before getting started', '{"items":[{"answer":"We offer a wide range of courses including web development, data science, cloud computing, cybersecurity, and competitive exam coaching for TNPSC, UPSC, SSC, Banking, and Railway exams.","question":"What courses do you offer?"},{"answer":"We offer both online and offline (hybrid) learning options. Our online courses include live sessions and recorded content, while offline classes are conducted at our training centers.","question":"Are your courses online or offline?"},{"answer":"Yes, we provide comprehensive placement assistance including resume building, mock interviews, and job referrals. Our placement support team works closely with industry partners to connect you with the right opportunities.","question":"Do you provide placement assistance?"},{"answer":"Course durations vary depending on the program. Short-term courses range from 2-3 months, while comprehensive programs span 4-6 months. Competitive exam coaching runs up to 8-10 months.","question":"What is the duration of your courses?"},{"answer":"Yes, you will receive a verified completion certificate upon successfully finishing the course. Our certificates are recognized by industry partners.","question":"Do I get a certificate after completing a course?"},{"answer":"Absolutely! We offer free demo classes for all our courses. Simply fill out the form on our website or contact us to schedule your free demo session.","question":"Can I get a free demo before enrolling?"}]}'::jsonb, TRUE, 10, '2026-08-24T04:34:29.468391+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "cta_left", "cta_right", "is_published", "created_at", "video_url", "nav_item_id", "duration", "mode", "status", "curriculum", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "rating", "review_count", "learner_count", "start_date") VALUES ('11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'react-js-development-course', 'React JS Development Course', NULL, 'aster React JS with our project-driven frontend course for students and professionals. Build scalable web apps using JavaScript, TypeScript, APIs, and state management through hands-on training and career guidance.', '["Master modern JS fundamentals required for React development.","Build reusable, scalable React components using modern architecture.","Develop responsive and accessible UI using modern React practices.","Work with React Hooks, Context API, forms, and component state.","Implement client-side routing for multi-page app experiences.","Integrate REST APIs, handle async data, loading states, and auth.","Use TypeScript with React to develop maintainable, type-safe apps.","Manage complex state using Context API and modern state tools.","Build secure login, protected routes, and role-based app features.","Create real-world apps with reusable components, APIs, and routing."]'::jsonb, 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/course-thumbnails/1786514099348-Gemini_Generated_Image_8y54o48y54o48y54.png', 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/course-thumbnails/1786514108500-Gemini_Generated_Image_8y54o48y54o48y54.png', 'Talk To Advisor', 'Download Brochure', TRUE, '2026-08-12T06:18:49.741743+00:00', 'https://www.youtube.com/watch?v=YOUR_VIDEO_ID', '1c20c76e-745b-4e87-9386-ef247c9c0e61', '3 months', 'Online', 'Active', '[]'::jsonb, FALSE, 'Ready to Build Your Future with React JS?', 'Learn React JS through practical projects, expert-led training, real-world development practices, and career-focused guidance. Start building production-ready applications and take the next step toward a successful frontend development career.', 'Enroll Now', '/contact', '+916380957390', 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/course-thumbnails/1786514205985-istockphoto-1388970018-170667a.jpg', 0, 0, 0, '2026-08-13T14:30:00+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "cta_left", "cta_right", "is_published", "created_at", "video_url", "nav_item_id", "duration", "mode", "status", "curriculum", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "rating", "review_count", "learner_count", "start_date") VALUES ('4689e3da-af9b-442e-8d1f-9b42af353ac8', 'html5-development-course', 'HTML5 Development Course', NULL, 'Master HTML5 through practical training in semantic web development, forms, multimedia, accessibility, SEO, browser features, and modern web standards. Build real-world projects and develop a strong foundation for CSS, JavaScript, React, and professional frontend development.
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "cta_left", "cta_right", "is_published", "created_at", "video_url", "nav_item_id", "duration", "mode", "status", "curriculum", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "rating", "review_count", "learner_count", "start_date") VALUES ('6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'uiux-design-masterclass', 'UI/UX Design Masterclass', NULL, 'Master UI/UX design from the fundamentals to advanced product design workflows through user research, information architecture, wireframing, visual design, prototyping, and design systems. Build practical digital experiences with modern tools and real-world projects while developing a portfolio that demonstrates your design thinking and execution.', '["UI Design Principles & Visual Hierarchy","UX Research & User-Centered Design","Information Architecture & User Flows","Wireframing & Interactive Prototyping","Figma & High-Fidelity UI Design","Responsive Design & Design Systems"]'::jsonb, 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/course-thumbnails/1786600004997-Gemini_Generated_Image_8y54o48y54o48y54.png', 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/course-thumbnails/1786600004997-Gemini_Generated_Image_8y54o48y54o48y54.png', 'Talk to Advisor', 'Download Brochure', TRUE, '2026-08-13T05:54:35.125731+00:00', 'https://youtu.be/ODpB9-MCa5s?si=Tifd-f638tSnct6Z', 'a2096488-1004-4f38-85cc-a6c948367571', '3 months', 'Online', 'Active', '[]'::jsonb, FALSE, 'Design Better Digital Experiences with UI/UX', 'Build job-ready UI/UX skills through practical projects, modern design tools, and expert-guided learning.', 'Apply Now', '', '', 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/course-thumbnails/1786600065535-cta.png', 0, 0, 0, '2026-08-13T06:21:00+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."courses" ("id", "slug", "title", "subtitle", "description", "checklist_items", "hero_image_url", "video_thumbnail_url", "cta_left", "cta_right", "is_published", "created_at", "video_url", "nav_item_id", "duration", "mode", "status", "curriculum", "show_pricing", "cta_heading", "cta_description", "cta_text", "cta_link", "cta_phone", "cta_background_image", "rating", "review_count", "learner_count", "start_date") VALUES ('a4209bc8-517d-46d9-9f20-a747d1f74dc2', 'test-3', 'test', NULL, NULL, '[]'::jsonb, NULL, NULL, 'Enroll Now', 'Download Brochure', TRUE, '2026-08-07T07:51:10.155741+00:00', NULL, NULL, '3 months', 'Online', 'Active', '[]'::jsonb, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, '2026-08-07T12:36:00+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('2ccd2776-e574-4845-97f8-28be6c527656', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'Overview', 'overview', '{"qa":[{"answers":["Build reusable React components and scalable application structures","Develop responsive and interactive web interfaces","Work with Hooks, Context API, forms, routing, and state management","Integrate REST APIs and manage asynchronous application data","Implement authentication and protected application routes","Use TypeScript with React for maintainable and type-safe development","Debug, optimize, test, and deploy React applications"],"question":"What Will You Learn in This React JS Course?"},{"answers":["Students looking to start a career in frontend development","Freshers preparing for React developer and software development roles","Web developers who want to upgrade their JavaScript and React skills","Developers moving from traditional frontend technologies to modern frameworks","Working professionals who want practical React application development experience","Entrepreneurs and aspiring developers who want to build modern web products"],"question":"Who should take this React JS Development Course?"}],"heading":"React JS Course Overview","paragraph":"This React JS Development Course is designed to take learners from JavaScript and React fundamentals to building scalable, production-ready web applications. You will learn how React works internally, how component-based architecture is designed, and how modern frontend applications communicate with backend services through APIs. The training focuses on practical development rather than theory alone, with hands-on exercises, debugging sessions, reusable UI development, API integration, authentication, state management, routing, TypeScript, and deployment. By the end of the course, you will have experience building complete React applications and a portfolio of practical projects that demonstrate your frontend development capabilities.","subheading":"","headingAlign":"center"}'::jsonb, 0) ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('56ae4330-6533-40fd-9891-3371d6fbdb06', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'Syllabus', 'syllabus', '{"qa":[],"heading":"React JS Course Curriculum","paragraph":"The React JS curriculum follows a progressive learning path that starts with the foundations of modern JavaScript and gradually moves into advanced React application development. Every module combines concepts with practical implementation so learners understand not only how to use React APIs, but also how to structure, debug, maintain, optimize, and deploy real-world applications.","subheading":"From JavaScript Fundamentals to Production-Ready React Applications"}'::jsonb, 1) ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('033f61cb-b8ce-4d76-9057-c8d831030dd2', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'Overview', 'overview', '{"qa":[{"answers":["HTML5 document structure and semantic elements","Forms, validation, multimedia, and embedded content","Accessibility and SEO-friendly HTML practices","Browser features, debugging, Git, and professional workflows"],"question":"What will I learn in this HTML5 course?"},{"answers":["HTML5 provides the structural foundation of modern websites","Semantic HTML improves accessibility and maintainability","HTML works with CSS and JavaScript to create complete web experiences","HTML knowledge is essential before learning frameworks such as React"],"question":"Why is HTML5 important for frontend development?"}],"heading":"HTML5 Development Course Overview","paragraph":"This HTML5 Development Course builds a strong foundation in modern web development through semantic HTML, forms, multimedia, accessibility, SEO, browser features, and professional coding practices. Learners work on practical websites while developing the skills required to create structured, maintainable, accessible, and production-ready web pages. The course also prepares learners for CSS, JavaScript, React, and modern frontend development.","headingAlign":"center","paragraphAlign":"left"}'::jsonb, 0) ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('db810fa2-58f9-48f4-8387-a346b47ef74b', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'Curriculum', 'syllabus', '{"qa":[{"answers":["HTML and web fundamentals","Semantic HTML5 and modern document structure","Forms, validation, and user input","Images, multimedia, SVG, and Canvas","Accessibility and SEO-friendly HTML","Browser APIs, storage, and debugging","Git, GitHub, validation, and deployment"],"question":"What topics are covered in the HTML5 curriculum?"},{"answers":["Yes, every major topic is reinforced through practical exercises","Learners create real-world website structures","Projects focus on professional HTML organization","Practical work prepares learners for CSS and JavaScript development"],"question":"Does the course include practical development?"}],"heading":"HTML5 Development Course Curriculum","paragraph":"The curriculum progresses from HTML fundamentals to professional web development practices. Learners study semantic structure, forms, multimedia, accessibility, SEO, browser capabilities, debugging, Git, and deployment while applying each concept through practical exercises and structured projects.","subheading":"From HTML Fundamentals to Professional Web Development","headingAlign":"center","paragraphAlign":"left"}'::jsonb, 1) ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('f73553ee-73ef-45dc-94a2-da763efc192c', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'Projects', 'overview', '{"qa":[{"answers":["Corporate business website","Personal developer portfolio","Online course landing page"],"question":"What type of projects will I build?"},{"answers":["Semantic HTML5 structure","Accessible forms and navigation","Multimedia and responsive-ready content","SEO-friendly and maintainable page organization"],"question":"What skills will the projects demonstrate?"}],"heading":"Real-World HTML5 Projects","paragraph":"Apply HTML5 concepts by building practical websites based on real-world development requirements. Projects focus on semantic structure, navigation, forms, accessibility, multimedia, SEO-friendly content, and professional page organization. These projects help learners develop practical experience and create a foundation for their frontend development portfolio.","subheading":"Build Practical Portfolio-Ready Websites","headingAlign":"center","paragraphAlign":"left"}'::jsonb, 2) ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('2a39c001-889c-4370-ab70-3c7d03a92756', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'Certification', 'overview', '{"qa":[{"answers":["HTML5 and semantic web development knowledge","Accessible and SEO-friendly page structure","Forms, multimedia, and modern HTML features","Practical website development skills"],"question":"What does the HTML5 certification validate?"},{"answers":["Complete the required course learning activities","Complete practical assignments","Successfully complete the course projects","Meet the required course evaluation criteria"],"question":"How is the certification awarded?"}],"heading":"HTML5 Development Certification","paragraph":"The Marvel Slice HTML5 Development Certification validates practical knowledge of modern HTML5 and professional web development fundamentals. Learners demonstrate their ability to create semantic, accessible, SEO-friendly, multimedia-rich, and maintainable web pages through practical assignments and project evaluation.","subheading":"Validate Your Modern Web Development Foundations","headingAlign":"center","paragraphAlign":"left"}'::jsonb, 3) ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('28573d6f-d9b5-4af3-a630-4609ff2e9277', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Overview', 'overview', '{"qa":[{"answers":["Figma for UI Design & Modern Design Systems","Miro & FigJam for User Research & Journey Mapping","ProtoPie for Micro-Interactions & Prototyping"],"question":"What key design tools will I master?"},{"answers":["Aspiring UI/UX Designers building a job-ready portfolio","Frontend Developers mastering UX design principles","Product Managers enhancing user interface design skills"],"question":"Who is this program designed for?"}],"heading":"Build Strong UI/UX Foundations","paragraph":"Learn the fundamentals of user-centered design and modern product design workflows, from understanding users and defining problems to creating intuitive and visually engaging digital experiences.","subheading":"","headingAlign":"left","subparagraph":"","paragraphAlign":"left","subheadingAlign":"left","subparagraphAlign":"left"}'::jsonb, 0) ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('a39d7578-ebeb-4158-8b28-2f5e248f3dbc', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Curriculum', 'overview', '{"qa":[{"answers":["User Personas & Customer Journey Maps","User Research Methods & Problem Definition","Information Architecture & Card Sorting","User Flows & Content Structure"],"question":"Module 1: User Research & Information Architecture"},{"answers":["Low-Fidelity Wireframes & Layout Structure","Navigation Patterns & Interaction Design","Usability Principles & User-Centered Design","Responsive UX Planning"],"question":"Module 2: Wireframing & UX Design"},{"answers":["Auto-Layout, Components & Variants","Color Palettes & Typography Scales","Reusable UI Components & Design Tokens","Responsive High-Fidelity Interface Design"],"question":"Module 3: Figma & Design Systems"},{"answers":["Interactive Prototypes & User Testing","Micro-Interactions & Motion Principles","Design Handoff & Developer Collaboration","Portfolio Case Study Presentation"],"question":"Module 4: Prototyping & Product Design"}],"heading":"Learn the Complete UI/UX Workflow","paragraph":"Progress from UX research and information architecture through wireframing, UI design, Figma, prototyping, responsive design, and scalable design systems.","subheading":"","headingAlign":"left","subparagraph":"","paragraphAlign":"left","subheadingAlign":"left","subparagraphAlign":"left"}'::jsonb, 1) ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('3193a501-09ee-4d42-b530-e0d265bef837', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Projects', 'overview', '{"qa":[{"answers":["End-to-end shopping experience design","User flows, wireframes, and responsive UI screens","High-fidelity mobile and desktop prototypes"],"question":"Capstone Project 1: E-Commerce App"},{"answers":["User research and persona development","Mobile-first information architecture and wireframes","Interactive Figma prototype with reusable components"],"question":"Capstone Project 2: Mobile Application"},{"answers":["Analytics dashboard information architecture","Data visualization-focused interface design","Scalable components and responsive design system"],"question":"Capstone Project 3: SaaS Dashboard"}],"heading":"Build Real-World Portfolio Projects","paragraph":"Apply your learning to realistic product design challenges and create polished portfolio projects that demonstrate research, problem-solving, visual design, and prototyping skills.","subheading":"","headingAlign":"left","subparagraph":"","paragraphAlign":"left","subheadingAlign":"left","subparagraphAlign":"left"}'::jsonb, 2) ON CONFLICT DO NOTHING;
INSERT INTO public."course_tabs" ("id", "course_id", "label", "content_type", "content", "sort_order") VALUES ('2d2e2dda-0557-445c-b234-c330b3e4c870', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Certification', 'overview', '{"qa":[{"answers":["Understanding of modern UI/UX design principles","Practical experience with research, UI design, and prototyping","Ability to create and present portfolio-ready digital experiences"],"question":"What does the certification demonstrate?"},{"answers":["Add the certification to your professional resume","Showcase it alongside your UI/UX portfolio","Use it as evidence of completed structured UI/UX training"],"question":"How can I use the certification professionally?"}],"heading":"Validate Your UI/UX Design Skills","paragraph":"Complete the learning program and practical projects to demonstrate your understanding of modern UI/UX workflows and earn a verified skill certification.","subheading":"","headingAlign":"left","subparagraph":"","paragraphAlign":"left","subheadingAlign":"left","subparagraphAlign":"left"}'::jsonb, 3) ON CONFLICT DO NOTHING;
