INSERT INTO public."highlights" ("id", "course_id", "icon", "label", "sort_order") VALUES ('4fec7fec-5a2f-405e-92b7-190c3c5ffaa5', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'zap', 'Career Support', 8) ON CONFLICT DO NOTHING;
INSERT INTO public."overview_faqs" ("id", "course_id", "question", "answer", "list_items", "sort_order") VALUES ('f68bb3b0-beb6-467b-8f91-de1ce15541fc', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'What key skills will I master in this program?', 'You will master UX research, user personas, customer journey mapping, information architecture, user flows, wireframing, visual hierarchy, UI design, prototyping, and design systems. The program emphasizes practical digital experiences and portfolio development so you can demonstrate both your design thinking and execution skills.', '[]'::jsonb, 0) ON CONFLICT DO NOTHING;
INSERT INTO public."overview_faqs" ("id", "course_id", "question", "answer", "list_items", "sort_order") VALUES ('f9f181a4-7a08-4dc6-83ee-2bbd205d13e7', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'How is the learning structured for working professionals?', 'The program follows a flexible, project-based learning structure with practical assignments and guided activities. Recorded sessions and portfolio-focused projects allow learners to continue practicing and completing their work at a pace that fits their schedule.', '[]'::jsonb, 1) ON CONFLICT DO NOTHING;
INSERT INTO public."overview_faqs" ("id", "course_id", "question", "answer", "list_items", "sort_order") VALUES ('6ec72c03-ff28-41d7-b85e-a5cc03c0d7e8', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'What tools will I use during the program?', 'The program introduces modern UI/UX workflows using tools such as Figma for interface design and design systems, Miro and FigJam for research and journey mapping, and ProtoPie for interactive prototypes and micro-interactions. The focus is on applying these tools to realistic product design workflows.', '[]'::jsonb, 2) ON CONFLICT DO NOTHING;
INSERT INTO public."projects" ("id", "course_id", "title", "description", "sort_order", "difficulty", "technologies") VALUES ('b2410e78-664f-49af-9a83-2c07a59246bc', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'E-Commerce UI/UX Design', 'Design an end-to-end e-commerce experience covering user research, user flows, wireframes, responsive UI screens, and high-fidelity interactive prototypes.', 0, NULL, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."projects" ("id", "course_id", "title", "description", "sort_order", "difficulty", "technologies") VALUES ('4303d01b-5341-43ef-9f21-19f4ecc8288f', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Mobile App Design', 'Create a modern mobile application from research and information architecture to wireframes, visual design, reusable components, and an interactive Figma prototype.', 1, NULL, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."projects" ("id", "course_id", "title", "description", "sort_order", "difficulty", "technologies") VALUES ('d6ec13f5-ee6a-4679-9c16-f36c1e34979d', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'SaaS Dashboard Design', 'Design a responsive SaaS analytics dashboard with data-focused layouts, reusable components, accessibility considerations, and a scalable design system.', 2, NULL, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."projects" ("id", "course_id", "title", "description", "sort_order", "difficulty", "technologies") VALUES ('55c49f92-cee5-45cc-8203-a335cba585d7', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'E-Commerce Shopping Platform', 'Build a responsive e-commerce application with product listings, category filtering, search, product details, shopping cart functionality, authentication, API integration, and responsive checkout interfaces.', 0, NULL, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."projects" ("id", "course_id", "title", "description", "sort_order", "difficulty", "technologies") VALUES ('fd758c3f-4b31-48cc-b93e-bf721994a226', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'Task & Project Management Dashboard', 'Develop a collaborative task management dashboard with authentication, project creation, task assignment, status tracking, filtering, search, dashboard statistics, and reusable React components.', 1, NULL, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."projects" ("id", "course_id", "title", "description", "sort_order", "difficulty", "technologies") VALUES ('7aec8618-d2e0-4283-90e3-ac7af19f8e9b', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'Learning Management Platform', 'Create a modern learning platform where users can browse courses, view course details, track learning progress, manage profiles, and interact with structured course content through reusable React components and API integration.', 2, NULL, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."projects" ("id", "course_id", "title", "description", "sort_order", "difficulty", "technologies") VALUES ('42b9183c-610f-4ef0-ae69-16bc38bebbf2', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'Corporate Business Website', 'Build a professional multi-page corporate website using semantic HTML5. Create structured sections for company information, services, about, team, contact details, navigation, and call-to-action areas while following accessibility and SEO-friendly HTML practices.', 0, NULL, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."projects" ("id", "course_id", "title", "description", "sort_order", "difficulty", "technologies") VALUES ('383e937f-4c16-4e53-bd59-f19893a138fe', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'Personal Developer Portfolio', 'Create a professional developer portfolio with profile, skills, projects, education, experience, services, contact information, and social links. Apply semantic HTML5 structure and organize the website for future CSS and JavaScript integration.', 1, NULL, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."projects" ("id", "course_id", "title", "description", "sort_order", "difficulty", "technologies") VALUES ('fb8fee42-397f-494e-b449-7f4e6b44be55', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'Online Course Landing Page', 'Develop a complete course landing page containing hero content, benefits, curriculum, instructor information, testimonials, pricing, FAQs, enrollment forms, and contact sections using clean semantic HTML5 and accessible page structures.', 2, NULL, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."certifications" ("id", "course_id", "description", "image_url", "certificate_image_url", "recognized_companies", "skills_earned") VALUES ('aa2949bc-495f-4ea7-9f09-7c984964d194', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'The Marvel Slice HTML5 Development Certification validates practical knowledge of modern HTML5 and professional web development. Learners demonstrate skills in semantic structure, accessibility, forms, multimedia, SEO-friendly markup, browser features, debugging, and real-world website development through practical assignments and project evaluation.', NULL, 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/certificates/1786539910210-certificate.png', '["Google","Microsoft","Amazon","IBM","Accenture","TCS","Infosys","Wipro","Cognizant","Capgemini","HCLTech","Tech Mahindra","Zoho","Freshworks","Oracle","Deloitte","EY","Genpact","UST","Mphasis"]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."certifications" ("id", "course_id", "description", "image_url", "certificate_image_url", "recognized_companies", "skills_earned") VALUES ('ced416a2-89f8-4bd3-89d5-11304dc3f994', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Earn a verified UI/UX Design certification upon successful completion of the course and practical projects. The certification validates your understanding of modern UI/UX workflows, design principles, prototyping, and design systems.', NULL, 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/certificates/1786600442759-certificate.png', '["Google","Microsoft","Adobe","IBM","Accenture"]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."certifications" ("id", "course_id", "description", "image_url", "certificate_image_url", "recognized_companies", "skills_earned") VALUES ('7d0435d0-4aba-4181-8cd2-1877db20ace5', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'The Marvel Slice React JS Development Certification validates practical knowledge of modern frontend development using React JS. Learners demonstrate their ability to create reusable component-based interfaces, manage application state, implement routing and authentication, integrate REST APIs, build responsive user experiences, work with TypeScript, debug applications, optimize performance, and deploy production-ready React applications. Certification is awarded after successful completion of the required learning activities, practical assignments, and course project evaluation.', NULL, 'https://nxlsxywqvvuiljsulito.supabase.co/storage/v1/object/public/certificates/1786515520055-certificate.png', '["Google","Microsoft","Amazon","IBM","Accenture","TCS","Infosys","Wipro","Cognizant","Capgemini","HCLTech","Tech Mahindra","Zoho","Freshworks","Oracle","Deloitte","EY","Genpact","UST","Mphasis"]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public."alumni_companies" ("id", "name", "logo_url", "sort_order") VALUES ('145c5a32-a1a7-4aac-83e6-d33c29619be3', 'tech', NULL, 0) ON CONFLICT DO NOTHING;
