INSERT INTO public."alumni_companies" ("id", "name", "logo_url", "sort_order") VALUES ('e84e041f-f910-4060-a3e7-b9a039bc8e80', 'gdfg', NULL, 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('32111922-f3b6-4c4b-8c97-47d5c8919d2a', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'What is HTML5 and why is it important for web development?', 'HTML5 is the modern standard markup language used to structure websites and web applications. It provides semantic elements, multimedia support, forms, accessibility features, metadata capabilities, and browser features. HTML5 forms the foundation for CSS, JavaScript, React, and modern frontend development.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('c50205d9-5a12-4d6f-b29e-1c2198c1f7e0', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'Do I need prior coding experience to learn HTML5?', 'No. The course starts with basic web concepts, HTML structure, elements, attributes, links, images, forms, and semantic markup. It gradually progresses into accessibility, SEO, browser features, debugging, Git, and practical website projects, making it suitable for beginners and aspiring developers.No. The course starts with basic web concepts, HTML structure, elements, attributes, links, images, forms, and semantic markup. It gradually progresses into accessibility, SEO, browser features, debugging, Git, and practical website projects, making it suitable for beginners and aspiring developers.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('a4622165-bf8d-4e44-9ca5-6cc07f6bbfb5', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'What projects will I build during the HTML5 course?', 'You will build a corporate business website, personal developer portfolio, and online course landing page. These projects provide practical experience with semantic HTML, navigation, forms, multimedia, accessibility, SEO-friendly structures, and professional website organization.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('a5cb466b-3eb0-4e7e-b277-b7d24abfb499', '4689e3da-af9b-442e-8d1f-9b42af353ac8', 'What can I learn after completing HTML5 training?', 'After HTML5, you can progress into CSS, JavaScript, responsive frontend development, React, Angular, Vue, or full-stack development. HTML5 provides the structural foundation required to understand and build modern frontend applications.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('72d94098-20ba-4ae2-84f6-5fbc7c17ca66', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Are there any prerequisites for this course?', 'No prior professional UI/UX experience is required. Basic computer knowledge and an interest in digital product design are recommended.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('8106c9b7-1531-4194-8e8d-2c5820f7aca8', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Who is this program suitable for?', 'The program is suitable for aspiring UI/UX designers, frontend developers who want to strengthen their UX skills, product managers, and learners who want to build a professional digital product design portfolio.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('3df1d2a9-4bc1-4587-9588-8323bf1206c5', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Will I receive a certificate after completing the course?', 'Yes, learners who successfully complete the course requirements will receive a verified UI/UX skill certification.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('69acdb9c-530d-4453-b2b5-bc4600c33e6b', '6c4d6a7b-9179-458d-8084-a27ec552fbe2', 'Will I build portfolio projects during the course?', 'Yes, the course includes practical projects covering e-commerce, mobile applications, and SaaS dashboard experiences. These projects can be developed into portfolio case studies that demonstrate your design process and final solutions.', 3) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('306f2986-28fc-4d50-ae94-9d446666e09d', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'What is React JS and why is it used for web development?', 'React JS is a JavaScript library for building interactive user interfaces using reusable components. It allows developers to divide complex interfaces into smaller, maintainable components and efficiently update the user interface when application data changes. React is widely used for modern single-page applications, dashboards, e-commerce platforms, SaaS products, portals, and other interactive web applications.', 0) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('6951921e-a816-4f66-9026-92fc44b6b946', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'Do I need prior React experience to join this course?', 'No. The course is structured progressively, starting with the JavaScript concepts required for React development before moving into components, JSX, Hooks, routing, APIs, state management, authentication, TypeScript, testing, performance, and deployment. Basic familiarity with computers and web concepts is helpful, while JavaScript fundamentals are developed as part of the learning path.', 1) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('7e8993fa-732b-46fd-9163-145e6b269119', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'What projects will I build during the React JS course?', 'You will work on practical applications such as an e-commerce platform, project management dashboard, learning management platform, and job and internship portal. Projects cover reusable components, responsive interfaces, API integration, authentication, routing, forms, state management, search, filtering, validation, and deployment. These projects are designed to provide portfolio-ready development experience.', 2) ON CONFLICT DO NOTHING;
INSERT INTO public."faqs" ("id", "course_id", "question", "answer", "sort_order") VALUES ('4ecfde67-9bb2-4865-b8df-5ceed9ef0f1f', '11d1004b-2240-41fb-bfe9-a4d201d70c8f', 'Will I receive a certificate after completing the React JS training?', 'Yes. Learners who successfully complete the required course activities, practical assignments, and project evaluation can receive a Marvel Slice React JS Development Certification. The certificate represents completion of practical training across React development, API integration, state management, routing, authentication, responsive UI development, TypeScript, debugging, and deployment concepts.', 3) ON CONFLICT DO NOTHING;
