INSERT INTO public."services" ("id", "title", "slug", "category_id", "icon", "thumbnail", "banner", "short_description", "description", "duration", "mode", "price", "discount", "badge", "difficulty", "language", "certificate", "placement_support", "internship", "eligibility", "curriculum", "learning_outcomes", "requirements", "featured", "popular", "trending", "status", "sort_order", "seo_title", "seo_description", "seo_keywords", "meta_image", "canonical_url", "created_by", "updated_by", "created_at", "updated_at") VALUES ('64dc726f-daed-4c88-ba5c-3d27cffe01cc', 'Certification Courses', 'certification-courses', '4a902005-d580-4406-b752-af2e6f344ea0', 'FiAward', NULL, NULL, 'Industry-recognized certification programs to validate your skills and boost your career prospects.', 'Our certification courses are designed to validate your expertise in specific domains. Each course includes comprehensive training, hands-on projects, and a final assessment. Upon successful completion, you receive a certification that is recognized by leading companies. The curriculum is regularly updated to align with industry standards and the latest technologies.', '2-6 Months', 'Online', 19999, 15, 'Trending', 'Intermediate', 'English', TRUE, TRUE, FALSE, 'Basic understanding of the subject area. Prior experience or completion of foundational course recommended.', '[{"items":["Core concepts","Industry overview","Tools setup","Basic terminology"],"title":"Foundation"},{"items":["Advanced concepts","Practical applications","Case studies","Best practices"],"title":"Core Modules"},{"items":["Domain-specific topics","Advanced techniques","Real-world scenarios","Expert sessions"],"title":"Specialization"},{"items":["Practice tests","Final assessment","Project submission","Viva voce"],"title":"Assessment"},{"items":["Certificate issuance","Digital badge","Portfolio addition","LinkedIn integration"],"title":"Certification"}]'::jsonb, '["Industry-recognized certification","Comprehensive curriculum"