INSERT INTO public."services" ("id", "title", "slug", "category_id", "icon", "thumbnail", "banner", "short_description", "description", "duration", "mode", "price", "discount", "badge", "difficulty", "language", "certificate", "placement_support", "internship", "eligibility", "curriculum", "learning_outcomes", "requirements", "featured", "popular", "trending", "status", "sort_order", "seo_title", "seo_description", "seo_keywords", "meta_image", "canonical_url", "created_by", "updated_by", "created_at", "updated_at") VALUES ('94d0e262-a8d1-4de5-90f7-a47aebf27312', 'Internship Programs', 'internship-programs', '86ff6842-1921-4eee-b571-c82e66aea013', 'FiBriefcase', NULL, NULL, 'Gain real-world experience with our industry-focused internship programs. Work on live projects under expert mentorship.', 'Our internship programs bridge the gap between academic learning and industry requirements. Students work on real-world projects, gain hands-on experience, and build a professional portfolio. Interns are mentored by industry experts and receive regular feedback to accelerate their learning. Successful interns receive a completion certificate and placement assistance.', '3-6 Months', 'Hybrid', 14999, 20, 'Popular', 'All Levels', 'English', TRUE, TRUE, TRUE, 'Students currently enrolled in or graduated from any degree program. Basic understanding of relevant field preferred but not mandatory.', '[{"items":["Company introduction","Team allocation","Goal setting","Tools & access setup"],"title":"Orientation & Onboarding"},{"items":["Domain training","Tool & technology training","Process familiarization","Mentor assignment"],"title":"Training Period"},{"items":["Live project assignment","Sprint planning","Code reviews","Client interactions"],"title":"Project Work"},{"items":["Mid-term review","Performance evaluation","Feedback sessions","Final presentation"],"title":"Assessment & Feedback"},{"items":["Certificate issuance","Letter of recommendation","Placement support","Alumni network access"],"title":"Completion"}]'::jsonb, '["Real-world project experience","Industry mentorship","Professional portfolio","Completion certificate","Placement assistance","Networking opportunities","Stipend for eligible interns","Letter of recommendation"]'::jsonb, '["Currently pursuing or completed graduation","Basic knowledge of relevant domain","Strong communication skills","Commitment of minimum 3 months"]'::jsonb, TRUE, TRUE, TRUE, 'published', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-21T16:25:21.375305+00:00', '2026-07-21T16:48:01.933845+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."services" ("id", "title", "slug", "category_id", "icon", "thumbnail", "banner", "short_description", "description", "duration", "mode", "price", "discount", "badge", "difficulty", "language", "certificate", "placement_support", "internship", "eligibility", "curriculum", "learning_outcomes", "requirements", "featured", "popular", "trending", "status", "sort_order", "seo_title", "seo_description", "seo_keywords", "meta_image", "canonical_url", "created_by", "updated_by", "created_at", "updated_at") VALUES ('cbbae75b-b5ad-4077-b2ef-ac83989052e9', 'Aptitude Training', 'aptitude-training', '60cb954a-ccb8-48a9-a730-904ed4371a46', 'FiBarChart2', NULL, NULL, 'Master quantitative aptitude, logical reasoning, and verbal ability for competitive exams and placements.', 'Our aptitude training program covers all aspects of aptitude testing including quantitative aptitude, logical reasoning, verbal ability, and data interpretation.', '2-3 Months', 'Hybrid', 7999, 10, '', 'Beginner', 'English', FALSE, FALSE, FALSE, 'Anyone preparing for competitive exams or placement tests. Basic mathematics knowledge at 10+2 level.', '[{"items":["Number systems","Percentage & averages","Ratio & proportion","Time, speed & distance","Profit & loss","Permutation & combination"],"title":"Quantitative Aptitude"},{"items":["Analytical reasoning","Data sufficiency","Puzzles","Syllogisms","Blood relations","Coding-decoding"],"title":"Logical Reasoning"},{"items":["Grammar","Vocabulary","Comprehension","Sentence correction","Para jumbles","Critical reasoning"],"title":"Verbal Ability"},{"items":["Tables & charts","Graphs","Caselets","Data analysis","DI-LR combo"],"title":"Data Interpretation"},{"items":["Full-length tests","Sectional tests","Timed practice","Performance analysis"],"title":"Mock Tests"}]'::jsonb, '["Strong aptitude foundation","Speed & accuracy","Test-taking strategies","Mock test practice","Performance analytics","Confidence building","Time management","Competitive edge"]'::jsonb, '["Basic mathematics knowledge","10+2 level education","Willingness to practice regularly","Access to computer/internet"]'::jsonb, FALSE, FALSE, FALSE, 'published', 7, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-21T16:25:21.375305+00:00', '2026-07-21T16:48:04.76511+00:00') ON CONFLICT DO NOTHING;
